function kv(pairs) {
  const list = element("dl", { className:"kv" });
  for (const [label, value] of pairs) {
    list.append(element("dt", { text:label }));
    const content = value instanceof Node ? value : element("span", { text:value ?? "—" });
    list.append(element("dd", {}, content));
  }
  return list;
}

